def grep(pattern, flags, files):
    flag_set = set(flags.split())
    multiple_files = len(files) > 1

    results = []
    for filename in files:
        with open(filename) as f:
            lines = f.readlines()

        for index, line in enumerate(lines, start=1):
            content = line.rstrip("\n")

            if "-x" in flag_set:
                if "-i" in flag_set:
                    matched = content.lower() == pattern.lower()
                else:
                    matched = content == pattern
            else:
                if "-i" in flag_set:
                    matched = pattern.lower() in content.lower()
                else:
                    matched = pattern in content

            if "-v" in flag_set:
                matched = not matched

            if matched:
                if "-l" in flag_set:
                    results.append(filename + "\n")
                    break

                prefix = ""
                if multiple_files:
                    prefix += filename + ":"
                if "-n" in flag_set:
                    prefix += str(index) + ":"
                results.append(prefix + line)

    return "".join(results)
